D = "\"Dragunity\""
NT = "1 o más monstruos que no sean Cantantes"
DT = "1 Cantante " + D + " + " + NT + "\n"
DW = "1 Cantante Dragón + 1 o más monstruos Bestia Alada que no sean Cantantes\n"
def each(n): return " Sólo puedes usar cada efecto de \"%s\" una vez por turno." % n
def once(n): return " Sólo puedes usar este efecto de \"%s\" una vez por turno." % n
ES = {
"Dragunity Brandistock": "Mientras esta carta esté equipada a un monstruo, ese monstruo puede realizar un segundo ataque durante cada Battle Phase.",
"Dragunity Corsesca": "Cuando un monstruo equipado con esta carta destruye un monstruo de tu adversario en batalla: puedes añadir a tu mano 1 monstruo de Nivel 4 o menor de tu Deck con el mismo Tipo y Atributo que el monstruo al que esta carta está equipada.",
"Dragunity Tribus": "Cuando esta carta sea Invocada de Modo Normal o Especial: puedes mandar al Cementerio 1 monstruo Dragón de Nivel 3 o menor de tu Deck.",
"Dragunity Arma Gram": "Puedes desterrar 2 monstruos Dragón y/o Bestia Alada de tu Cementerio; Invoca esta carta de Modo Especial desde tu mano o Cementerio. Puedes seleccionar 1 monstruo boca arriba; sus efectos son negados, y además pierde 1000 ATK por cada Carta de Equipo que controles. Cuando un monstruo de tu adversario es destruido en batalla y mandado al Cementerio: puedes equiparlo a esta carta." + each("Dragunity Arma Gram"),
"Dragunity Aklys": "Cuando esta carta sea Invocada de Modo Normal: puedes Invocar de Modo Especial 1 monstruo " + D + " de tu mano y después equiparle esta carta. Si esta carta es mandada al Cementerio mientras está equipada a un monstruo: selecciona 1 carta en el Campo; destrúyela.",
"Dragunity Couse": "No puede ser usado como Material de Sincronía, excepto para la Invocación por Sincronía de un monstruo " + D + ". Esta carta en el Campo puede ser tratada como un monstruo de Nivel 4 cuando se use para una Invocación por Sincronía. Si esta carta está equipada a un monstruo: puedes Invocar de Modo Especial esta carta equipada.",
"Dragunity Falchion": "Puedes desterrar esta carta de tu mano o Cementerio y después seleccionar 1 monstruo " + D + " que controles; equípale, como Carta Mágica de Equipo, 1 monstruo Dragón " + D + " de tu Deck o Cementerio. Mientras esta carta esté equipada a un monstruo " + D + ": puedes mandar esta carta al Cementerio y después seleccionar 1 carta boca arriba que controle tu adversario; destiérrala." + each("Dragunity Falchion"),
"Dragunity Javelin": "Si esta carta boca arriba es destruida mientras está en una Zona de Monstruos, puedes equiparla a 1 monstruo Bestia Alada " + D + " que controles, en lugar de mandarla al Cementerio.",
"Dragunity Partisan": "Cuando esta carta sea Invocada de Modo Normal: puedes Invocar de Modo Especial 1 monstruo Bestia Alada " + D + " de tu mano y después equiparle esta carta. Mientras esta carta esté equipada a un monstruo, ese monstruo se trata como Cantante.",
"Dragunity Phalanx": "Una vez por turno, mientras esta carta esté equipada a un monstruo: puedes Invocar de Modo Especial esta carta equipada.",
"Dragunity Remus": "No puede ser usado como Material de Sincronía, excepto para la Invocación por Sincronía de un monstruo " + D + ". Puedes descartar esta carta; añade a tu mano 1 \"Dragon Ravine\" de tu Deck. Si controlas un monstruo " + D + ": puedes Invocar esta carta de Modo Especial desde tu Cementerio, pero destiérrala cuando deje el Campo, y además no puedes Invocar monstruos de Modo Especial desde el Deck Extra durante el resto de este turno, excepto monstruos Dragón." + each("Dragunity Remus"),
"Dragunity Darkspear": "Una vez por turno: puedes Sacrificar 1 monstruo Dragón " + D + " y después seleccionar 1 monstruo Bestia Alada de Nivel 4 o menor en tu Cementerio; Invoca de Modo Especial ese objetivo.",
"Dragunity Guisarme": "Cuando esta carta sea Invocada de Modo Normal: puedes seleccionar 1 monstruo Dragón o Bestia Alada de VIENTO de Nivel 4 o menor en tu Cementerio; Invócalo de Modo Especial, pero niega sus efectos. Mientras esta carta esté equipada a un monstruo: puedes Invocar de Modo Especial esta carta equipada." + each("Dragunity Guisarme"),
"Dragunity Legionnaire": "Cuando esta carta sea Invocada de Modo Normal: puedes seleccionar 1 monstruo Dragón " + D + " de Nivel 3 o menor en tu Cementerio; equipa ese objetivo a esta carta. Puedes mandar al Cementerio 1 carta " + D + " de tu Zona de Magia y Trampa y después seleccionar 1 monstruo boca arriba que controle tu adversario; destruye ese objetivo.",
"Dragunity Pilum": "Cuando esta carta sea Invocada de Modo Normal: puedes Invocar de Modo Especial 1 monstruo Bestia Alada " + D + " de tu mano y después equiparle esta carta. Mientras esta carta esté equipada a un monstruo, ese monstruo puede atacar directamente a tu adversario, pero cuando lo haga usando este efecto, el daño de batalla infligido a tu adversario se reduce a la mitad.",
"Dragunity Dux": "Gana 200 ATK por cada carta " + D + " que controles. Cuando esta carta sea Invocada de Modo Normal: puedes seleccionar 1 monstruo Dragón " + D + " de Nivel 3 o menor en tu Cementerio; equipa ese objetivo a esta carta.",
"Dragunity Legatus": "Si controlas \"Dragon Ravine\" o un monstruo " + D + ": puedes Invocar esta carta de Modo Especial desde tu mano. Si hay una o más Cartas de Monstruo " + D + " en tu Zona de Magia y Trampa: puedes seleccionar 1 Carta Mágica/de Trampa en el Campo; destrúyela." + each("Dragunity Legatus"),
"Dragunity Militum": "Una vez por turno: puedes seleccionar 1 carta " + D + " en tu Zona de Magia y Trampa; Invócala de Modo Especial.",
"Dragunity Quirinus": "Mientras esta carta esté equipada con una Carta de Equipo, tus monstruos " + D + " no pueden ser destruidos en batalla. Sólo puedes usar cada uno de los siguientes efectos de \"Dragunity Quirinus\" una vez por turno. Si esta carta es Invocada de Modo Normal o Especial: puedes añadir a tu mano 1 Carta Mágica/de Trampa " + D + " de tu Deck. Puedes seleccionar otra Carta de Monstruo " + D + " que controles; devuélvela a la mano/Deck Extra y después puedes Invocar de Modo Especial 1 monstruo " + D + " de tu mano.",
"Dragunity Senatus": "Puedes descartar 1 carta " + D + "; equipa a esta carta 1 Cantante " + D + " de tu Deck, y además no puedes Invocar monstruos de Modo Especial desde el Deck Extra durante el resto de este turno, excepto monstruos Dragón." + once("Dragunity Senatus") + " Si una o más cartas " + D + " que controles fueran a ser destruidas en batalla o por efecto de una carta, puedes destruir 1 carta " + D + " equipada a esta carta en su lugar.",
"Dragunity Angusticlavii": "Si esta carta ataca a un monstruo en Posición de Defensa mientras está equipada con un monstruo Dragón " + D + ", inflige daño de batalla de penetración.",
"Dragunity Primus Pilus": "Cuando esta carta sea Invocada de Modo Normal o Especial: puedes seleccionar 1 monstruo Bestia Alada " + D + " que controles; equípale 1 monstruo Dragón " + D + " de Nivel 3 o menor de tu Deck.",
"Dragunity Arma Mystletainn": "Puedes Invocar esta carta de Modo Especial (desde tu mano) mandando al Cementerio 1 monstruo " + D + " boca arriba que controles. Cuando esta carta sea Invocada de Modo Normal o Especial desde la mano: puedes seleccionar 1 monstruo Dragón " + D + " en tu Cementerio; equipa ese objetivo a esta carta.",
"Dragunity Arma Leyvaten": "Puedes Invocar esta carta de Modo Especial (desde tu mano o Cementerio) desterrando 1 monstruo que controles y que esté equipado con una o más cartas " + D + ". Cuando esta carta sea Invocada de Modo Normal o Especial: puedes seleccionar 1 monstruo Dragón en tu Cementerio, excepto \"Dragunity Arma Leyvaten\"; equipa ese objetivo a esta carta. Cuando esta carta que controlas es mandada a tu Cementerio por efecto de una carta de tu adversario: puedes seleccionar 1 de los monstruos que estaban equipados a esta carta cuando fue mandada al Cementerio; Invoca ese monstruo de Modo Especial.",
"Dragon Mastery": "Cada monstruo que controles y que esté equipado con uno o más monstruos " + D + " gana 500 ATK. Una vez por turno, puedes seleccionar 1 monstruo boca arriba que controles y equiparle 1 monstruo Dragón " + D + " de tu mano.",
"Dragon Ravine": "Una vez por turno: puedes descartar 1 carta y después activar 1 de estos efectos:\n● Añade a tu mano 1 monstruo " + D + " de Nivel 4 o menor de tu Deck.\n● Manda al Cementerio 1 monstruo Dragón de tu Deck.",
"Dragunity Divine Lance": "Equipa sólo a un monstruo " + D + ". Gana ATK igual a su Nivel x 100, y además no es afectado por efectos de Cartas de Trampa. Durante tu Main Phase: puedes equipar 1 Cantante Dragón " + D + " de tu Deck al monstruo equipado con esta carta." + once("Dragunity Divine Lance"),
"Dragunity Divine Wind": "Durante tu Main Phase: puedes aplicar 1 de estos efectos o, si \"Dragon Ravine\" está en tu Cementerio, puedes aplicar cualquiera de ellos, en secuencia:\n● Añade a tu mano 1 monstruo Dragón o Bestia Alada de tu Cementerio.\n● Invoca de Modo Especial 1 monstruo " + D + " de tu mano y después puedes equiparle, como Carta Mágica de Equipo, 1 monstruo Dragón " + D + " de tu Deck.\nSólo puedes usar este efecto de \"Dragunity Divine Wind\" una vez por turno.",
"Dragunity Draft": "Cuando esta carta es activada: puedes seleccionar 1 monstruo " + D + " de Nivel 4 o menor en tu Cementerio; añádelo a tu mano. Si tu monstruo " + D + " cuyo Nivel original es 5 o mayor ataca, no es afectado por efectos de cartas de tu adversario hasta el final del Damage Step. Sólo puedes activar 1 \"Dragunity Draft\" por turno.",
"Dragunity Glow": "Añade a tu mano 1 monstruo " + D + " de Nivel 5 o mayor de tu Deck o Cementerio. Puedes desterrar esta carta de tu Cementerio y después seleccionar 1 Carta de Monstruo en tu Zona de Magia y Trampa equipada a un monstruo " + D + "; Invócala de Modo Especial en Posición de Defensa." + each("Dragunity Glow"),
"Dragunity Whirlwind": "Si sólo tu adversario controla un monstruo: puedes Invocar de Modo Especial 1 Cantante " + D + " y 1 monstruo Bestia Alada " + D + " de tu Deck, pero niega sus efectos, y después, si tu adversario controla un monstruo que fue Invocado de Modo Especial desde el Deck Extra, inmediatamente después de que este efecto se resuelva puedes Invocar por Sincronía 1 Monstruo de Sincronía Dragón usando sólo monstruos " + D + " que controles. Durante el resto de este turno después de que esta carta se resuelva, no puedes Invocar monstruos de Modo Especial desde el Deck Extra, excepto monstruos Dragón. Sólo puedes activar 1 \"Dragunity Whirlwind\" por turno.",
"Dragunity Knight - Areadbhair": DT + "Cuando tu adversario activa un efecto de monstruo (Efecto Rápido): puedes desterrar 1 monstruo " + D + " de tu Cementerio; niega la activación y, si lo haces, destierra esa carta. Si esta carta destruye un monstruo de tu adversario en batalla, después del cálculo de daño: puedes desterrar ese monstruo de tu adversario. Si esta carta Invocada por Sincronía bajo el control de su dueño es destruida por una carta de tu adversario: puedes destruir todas las Cartas Mágicas y de Trampa que controle tu adversario." + each("Dragunity Knight - Areadbhair"),
"Dragunity Knight - Areus": "1 Cantante + 1 o más Monstruos de Sincronía que no sean Cantantes\nPuedes seleccionar cartas boca arriba que controle tu adversario, hasta el número de Cartas de Monstruo boca arriba en tu Zona de Magia y Trampa; niega sus efectos hasta el final de este turno. Éste es un Efecto Rápido si esta carta está equipada con una Carta de Equipo. Mientras esta carta esté equipada a un monstruo: puedes Invocar esta carta de Modo Especial y después puedes Invocar de Modo Especial 1 Cantante " + D + " de tu Cementerio." + each("Dragunity Knight - Areus"),
"Dragunity Knight - Ascalon": DT + "Puedes desterrar 1 monstruo " + D + " de tu Cementerio y después seleccionar 1 monstruo que controle tu adversario; destiérralo. Si esta carta Invocada por Sincronía bajo el control de su dueño es destruida por una carta de tu adversario: puedes Invocar de Modo Especial 1 Monstruo de Sincronía " + D + " con 3000 ATK o menos de tu Deck Extra. (Esto se trata como una Invocación por Sincronía.)" + once("Dragunity Knight - Ascalon"),
"Dragunity Knight - Barcha": DW + "Cuando esta carta sea Invocada por Sincronía: puedes seleccionar cualquier número de monstruos Dragón " + D + " en tu Cementerio; equipa esos monstruos Dragón a esta carta. Esta carta gana 300 ATK por cada carta " + D + " equipada a ella.",
"Dragunity Knight - Gae Bulg": DW + "Una vez por batalla, si esta carta batalla, durante el Damage Step (Efecto Rápido): puedes desterrar 1 monstruo Bestia Alada de tu Cementerio; esta carta gana el ATK original de ese monstruo hasta el final de este turno.",
"Dragunity Knight - Gae Dearg": DW + "Una vez por turno: puedes añadir a tu mano 1 monstruo Dragón o Bestia Alada de Nivel 4 o menor de tu Deck y después descartar 1 monstruo Dragón o Bestia Alada.",
"Dragunity Knight - Gormfaobhar": DT + "Cuando esta carta sea Invocada por Sincronía: puedes seleccionar 1 Cantante " + D + " en tu Cementerio; equípalo a esta carta. (Efecto Rápido): puedes mandar al Cementerio 1 Carta de Equipo que controles y que esté equipada a esta carta, y después seleccionar hasta 2 cartas en el Cementerio de tu adversario; destiérralas." + each("Dragunity Knight - Gormfaobhar"),
"Dragunity Knight - Luin": DT + "Si esta carta es Invocada de Modo Especial: puedes seleccionar 1 monstruo " + D + " en tu Cementerio; equípalo a esta carta. Si esta carta es mandada al Cementerio: puedes seleccionar 1 monstruo " + D + " que controles; equipa esta carta a ese objetivo. Gana 1000 ATK/DEF." + each("Dragunity Knight - Luin"),
"Dragunity Knight - Trident": DW + "Una vez por turno: puedes mandar al Cementerio hasta 3 cartas que controles; mira el Deck Extra de tu adversario y, si lo haces, manda de ahí al Cementerio el mismo número de cartas.",
"Dragunity Knight - Vajrayana": DW + "Cuando esta carta sea Invocada por Sincronía: puedes seleccionar 1 monstruo Dragón " + D + " de Nivel 3 o menor en tu Cementerio; equipa ese objetivo a esta carta. Una vez por turno: puedes mandar al Cementerio 1 Carta de Equipo que controles equipada a esta carta; duplica el ATK de esta carta hasta el final de este turno.",
"Dragunity Legion": "Puedes activar 1 de estos efectos, pero no puedes Invocar monstruos de Modo Especial durante el resto de este turno, excepto monstruos " + D + ".\n● Selecciona 1 Carta de Monstruo " + D + " en tu Zona de Magia y Trampa; Invócala de Modo Especial en Posición de Defensa.\n● Selecciona 1 monstruo " + D + " que controles; equipa a ese objetivo 1 monstruo " + D + " de tu Cementerio.\nSólo puedes usar este efecto de \"Dragunity Legion\" una vez por turno.",
"Dragunity Oubliette": "Cuando tu adversario activa una Carta Mágica/de Trampa mientras controlas un Monstruo de Sincronía " + D + ": niega la activación y, si lo haces, destierra esa carta, y después, si controlas un monstruo " + D + " de Nivel 10, puedes hacer que 1 monstruo " + D + " que controles gane 100 ATK por cada carta boca arriba que esté desterrada en este momento. Sólo puedes activar 1 \"Dragunity Oubliette\" por turno.",
}
